<section class="dash-card jobs-card" id="jobs"><div class="card-title"><h2>پروژه‌های پیشنهادی</h2><span><?=count($jobs)?> پروژه باز</span></div><?php foreach($jobs as $job):?><article class="job-item"><div class="job-info"><h3><?=e($job['title'])?></h3><p><?=e(mb_strimwidth($job['description'],0,150,'…'))?></p><small>بودجه: <?=e($job['budget_min'])?> تا <?=e($job['budget_max'])?> دلار</small></div><?php if((int)$job['already_applied']):?><span class="applied">ارسال شده</span><?php else:?><details><summary class="button button-small">ارسال پیشنهاد</summary><form class="proposal-form" method="post" action="<?=url('/dashboard/freelancer/proposals')?>"><?=csrf_field()?><input type="hidden" name="job_id" value="<?=e($job['id'])?>"><label>مبلغ پیشنهادی<input type="number" name="bid_amount" min="1" required></label><label>متن پیشنهاد<textarea name="cover_letter" rows="3" required></textarea></label><button class="button" type="submit">ثبت پیشنهاد</button></form></details><?php endif;?></article><?php endforeach;?><?php if(!$jobs):?><p class="empty-state">پروژه‌ای برای نمایش وجود ندارد.</p><?php endif;?></section>